using SWLOR.Game.Server.Enumeration;

namespace SWLOR.Game.Server.Service.AstromechService
{
    /// <summary>
    /// The astromech form of a humanoid item. An astromech equips only astromech modules and tools, so wherever the
    /// game hands a character a piece of humanoid equipment (a quest reward), an astromech receives the form it can use:
    /// the same stats on a module or tool. The table is generated by tools/GenerateAstromechRewards.py.
    /// </summary>
    public static partial class AstromechItemTwins
    {
        /// <summary>
        /// The item a character of this body frame receives in place of <paramref name="resref"/>: its astromech form
        /// for an astromech when one exists, otherwise the item itself.
        /// </summary>
        public static string Resolve(string resref, BodyFrame frame)
        {
            if (frame != BodyFrame.Astromech || string.IsNullOrEmpty(resref))
                return resref;

            return Twins.TryGetValue(resref, out var twin) ? twin : resref;
        }

        /// <summary>
        /// The item this creature receives in place of <paramref name="resref"/>.
        /// </summary>
        public static string Resolve(string resref, uint creature)
        {
            return Resolve(resref, Race.GetBodyFrame(creature));
        }

        /// <summary>
        /// True if a humanoid item has an astromech form.
        /// </summary>
        public static bool HasTwin(string resref)
        {
            return !string.IsNullOrEmpty(resref) && Twins.ContainsKey(resref);
        }
    }
}
